const email = $json;

let content = '';

if (typeof email.text === 'string') {
  content = email.text;
} else if (typeof email.html === 'string') {
  content = email.html
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, ' ');
}

content = content
  .replace(/\s+/g, ' ')
  .trim();

// Extract the expected resolution time from the email.
const match = content.match(
  /(?:resolution\s*time|tmo|tiempo\s*(?:de\s*)?resoluci[oó]n)\s*[:\-]\s*(\d+(?:[.,]\d+)?)\s*(?:minutes?|mins?|minutos?)?/i
);

const resolutionTimeMinutes = match
  ? Number(match[1].replace(',', '.'))
  : null;

let tmoCategory = 'Not Specified';

if (
  resolutionTimeMinutes !== null &&
  Number.isFinite(resolutionTimeMinutes) &&
  resolutionTimeMinutes >= 0
) {
  if (resolutionTimeMinutes <= 5) {
    tmoCategory = 'Within Target';
  } else if (resolutionTimeMinutes <= 30) {
    tmoCategory = 'Delayed - Within Limit';
  } else {
    tmoCategory = 'Critical';
  }
}

return {
  json: {
    email_id: email.id || '',
    sender: email.from?.text || email.From || '',
    subject: email.subject || email.Subject || '',
    email_text: content,
    resolution_time_minutes: resolutionTimeMinutes,
    tmo_category: tmoCategory
  }
};

const analysis = $input.item.json.output;
const email = $('Prepare Email Data').item.json;

// Get resolution time and TMO category from the original email
const resolutionTime = email.resolution_time_minutes;

const tmoCategory = email.tmo_category || 'Not specified';

const resolutionTimeText =
  resolutionTime !== null &&
  resolutionTime !== undefined &&
  String(resolutionTime).trim() !== ''
    ? `${resolutionTime} minutes`
    : 'Not specified';

// Normalize criticality to prevent capitalization or spacing issues
const rawCriticality = String(analysis.criticality || '')
  .trim()
  .toLowerCase();

let criticality;

if (rawCriticality === 'critical') {
  criticality = 'Critical';
} else if (
  rawCriticality === 'non-critical' ||
  rawCriticality === 'non critical' ||
  rawCriticality === 'noncritical'
) {
  criticality = 'Non-Critical';
} else {
  criticality = 'Needs Review';
}

// Build the complete analysis text
const analysisText = [
  `Email Summary: ${analysis.email_summary || 'Not available'}`,
  `Email Category: ${analysis.email_category || 'Not available'}`,
  `Criticality: ${criticality}`,
  `Resolution Time: ${resolutionTimeText}`,
  `TMO Category: ${tmoCategory}`,
  `Recommended Action: ${analysis.recommended_action || 'Not available'}`,
  `Reason: ${analysis.reason || 'Not available'}`
].join('\n');

const safeEmailId = String(email.email_id || Date.now())
  .replace(/[^a-zA-Z0-9_-]/g, '');

return {
  json: {
    email_id: email.email_id,
    sender: email.sender,
    subject: email.subject,
    email_text: email.email_text,
    email_summary: analysis.email_summary || 'Not available',
    email_category: analysis.email_category || 'Not available',
    criticality: criticality,
    resolution_time_minutes: resolutionTime,
    tmo_category: tmoCategory,
    recommended_action: analysis.recommended_action || 'Not available',
    reason: analysis.reason || 'Not available',
    analysis_text: analysisText,
    analysis_file_name: `Email_Analysis_${safeEmailId}.txt`
  }
};

const email = $('Prepare Email Data').first().json;

const originalEmail = `Original Email
Sender: ${email.sender || 'Unknown'}
Subject: ${email.subject || 'No subject'}
Email ID: ${email.email_id || 'Unknown'}

Email Content:
${email.email_text || 'No content available'}
`;

const safeId = String(email.email_id || Date.now())
  .replace(/[^a-zA-Z0-9_-]/g, '');

return {
  json: {
    ...email,
    original_email_text: originalEmail,
    original_file_name: `Original_Email_${safeId}.txt`
  }
};
